@Override
    public void visitSource(String sourceName, SCMSourceObserver observer)
            throws IOException, InterruptedException {
        TaskListener listener = observer.getListener();

        // Input data validation
        if (repoOwner.isEmpty()) {
            throw new AbortException("Must specify user or organization");
        }

        StandardCredentials credentials =
                Connector.lookupScanCredentials((Item)observer.getContext(), apiUri, scanCredentialsId);

        // Github client and validation
        GitHub github = Connector.connect(apiUri, credentials);
        try {
            try {
                github.checkApiUrlValidity();
            } catch (HttpException e) {
                String message = String.format("It seems %s is unreachable",
                        apiUri == null ? GitHubSCMSource.GITHUB_URL : apiUri);
                throw new AbortException(message);
            }

            // Input data validation
            if (credentials != null && !github.isCredentialValid()) {
                String message = String.format("Invalid scan credentials %s to connect to %s, skipping",
                        CredentialsNameProvider.name(credentials),
                        apiUri == null ? GitHubSCMSource.GITHUB_URL : apiUri);
                throw new AbortException(message);
            }

            if (!github.isAnonymous()) {
                listener.getLogger()
                        .format("Connecting to %s using %s%n", apiUri == null ? GitHubSCMSource.GITHUB_URL : apiUri,
                                CredentialsNameProvider.name(credentials));
                GHMyself myself = null;
                try {
                    // Requires an authenticated access
                    myself = github.getMyself();
                } catch (RateLimitExceededException rle) {
                    throw new AbortException(rle.getMessage());
                }
                if (myself != null && repoOwner.equalsIgnoreCase(myself.getLogin())) {
                    listener.getLogger().format("Looking up %s repository of myself %s%n%n", sourceName, repoOwner);
                    GHRepository repo = myself.getRepository(sourceName);
                    if (repo != null && repo.getOwnerName().equals(repoOwner)) {
                        add(listener, observer, repo);
                    }
                    return;
                }
            } else {
                listener.getLogger().format("Connecting to %s with no credentials, anonymous access%n",
                        apiUri == null ? GitHubSCMSource.GITHUB_URL : apiUri);
            }

            GHOrganization org = null;
            try {
                org = github.getOrganization(repoOwner);
            } catch (RateLimitExceededException rle) {
                throw new AbortException(rle.getMessage());
            } catch (FileNotFoundException fnf) {
                // may be an user... ok to ignore
            }
            if (org != null && repoOwner.equalsIgnoreCase(org.getLogin())) {
                listener.getLogger().format("Looking up %s repository of organization %s%n%n", sourceName, repoOwner);
                GHRepository repo = org.getRepository(sourceName);
                if (repo != null) {
                    add(listener, observer, repo);
                }
                return;
            }

            GHUser user = null;
            try {
                user = github.getUser(repoOwner);
            } catch (RateLimitExceededException rle) {
                throw new AbortException(rle.getMessage());
            } catch (FileNotFoundException fnf) {
                // the user may not exist... ok to ignore
            }
            if (user != null && repoOwner.equalsIgnoreCase(user.getLogin())) {
                listener.getLogger().format("Looking up %s repository of user %s%n%n", sourceName, repoOwner);
                GHRepository repo = user.getRepository(sourceName);
                if (repo != null) {
                    add(listener, observer, repo);
                }
                return;
            }

            throw new AbortException(repoOwner + " does not correspond to a known GitHub User Account or Organization");
        } finally {
            Connector.release(github);
        }
    }

protected void doSend(HttpServletResponse response)
            throws IOException {

        response.setContentType("text/html");
        response.setCharacterEncoding("UTF-8");

        // get changelog
        changes.insert(0, "<pre>");
        changes.append("</pre>");
        setProperty(PN_CHANGE_LOG, changes.toString());

        Writer out = response.getWriter();
        InputStream template = getClass().getResourceAsStream(TEMPLATE_NAME);
        Reader in = new BufferedReader(new InputStreamReader(template));
        StringBuffer varBuffer = new StringBuffer();
        int state = 0;
        int read;
        while ((read = in.read()) >= 0) {
            char c = (char) read;
            switch (state) {
                // initial
                case 0:
                    if (c == '$') {
                        state = 1;
                    } else {
                        out.write(c);
                    }
                    break;
                // $ read
                case 1:
                    if (c == '{') {
                        state = 2;
                    } else {
                        state = 0;
                        out.write('$');
                        out.write(c);
                    }
                    break;
                // { read
                case 2:
                    if (c == '}') {
                        state = 0;
                        Object prop = getProperty(varBuffer.toString());
                        if (prop != null) {
                            out.write(ResponseUtil.escapeXml(prop.toString()));
                        }
                        varBuffer.setLength(0);
                    } else {
                        varBuffer.append(c);
                    }
            }
        }
        in.close();
        out.flush();
    }

protected Number parseNumber(String s) throws ParseException {
		// pos
		int p = 0;
		// len
		int l = s.length();
		// max pos long base 10 len
		int max = 19;
		boolean neg;

		if (s.charAt(0) == '-') {
			p++;
			max++;
			neg = true;
			if (!acceptLeadinZero && l >= 3 && s.charAt(1) == '0')
				throw new ParseException(pos, ERROR_UNEXPECTED_LEADING_0, s);
		} else {
			neg = false;
			if (!acceptLeadinZero && l >= 2 && s.charAt(0) == '0')
				throw new ParseException(pos, ERROR_UNEXPECTED_LEADING_0, s);
		}

		boolean mustCheck;
		if (l < max) {
			max = l;
			mustCheck = false;
		} else if (l > max) {
			return new BigInteger(s, 10);
		} else {
			max = l - 1;
			mustCheck = true;
		}

		long r = 0;
		while (p < max) {
			r = (r * 10L) + ('0' - s.charAt(p++));
		}
		if (mustCheck) {
			boolean isBig;
			if (r > -922337203685477580L) {
				isBig = false;
			} else if (r < -922337203685477580L) {
				isBig = true;
			} else {
				if (neg)
					isBig = (s.charAt(p) > '8');
				else
					isBig = (s.charAt(p) > '7');
			}
			if (isBig)
				return new BigInteger(s, 10);
			r = r * 10L + ('0' - s.charAt(p));
		}
		if (neg) {
			if (this.useIntegerStorage && r >= Integer.MIN_VALUE)
				return (int) r;
			return r;
		}
		r = -r;
		if (this.useIntegerStorage && r <= Integer.MAX_VALUE)
			return (int) r;
		return r;
	}

