public void expand(final ZipFile archive, File targetDirectory)
        throws IOException, ArchiveException {
        final Enumeration<ZipArchiveEntry> entries = archive.getEntries();
        expand(new ArchiveEntrySupplier() {
            @Override
            public ArchiveEntry getNextReadableEntry() throws IOException {
                ZipArchiveEntry next = entries.hasMoreElements() ? entries.nextElement() : null;
                while (next != null && !archive.canReadEntryData(next)) {
                    next = entries.hasMoreElements() ? entries.nextElement() : null;
                }
                return next;
            }
        }, new EntryWriter() {
            @Override
            public void writeEntryDataTo(ArchiveEntry entry, OutputStream out) throws IOException {
                try (InputStream in = archive.getInputStream((ZipArchiveEntry) entry)) {
                    IOUtils.copy(in, out);
                }
            }
        }, targetDirectory);
    }

public static ByteBuffer alignDirectBuffer(ByteBuffer buffer, int alignment) {
        if (!buffer.isDirect()) {
            throw new IllegalArgumentException("Cannot get aligned slice of non-direct byte buffer.");
        }
        if (PlatformDependent0.hasAlignSliceMethod()) {
            return PlatformDependent0.alignSlice(buffer, alignment);
        }
        if (hasUnsafe()) {
            long address = directBufferAddress(buffer);
            long aligned = align(address, alignment);
            buffer.position((int) (aligned - address));
            return buffer.slice();
        }
        // We don't have enough information to be able to align any buffers.
        throw new UnsupportedOperationException("Cannot align direct buffer. " +
                "Needs either Unsafe or ByteBuffer.alignSlice method available.");
    }

