@Test(expected = IndexOutOfBoundsException.class)
    public void testReaderIndexLargerThanWriterIndex() {
        String content1 = "hello";
        String content2 = "world";
        int length = content1.length() + content2.length();
        ByteBuf buffer = newBuffer(length);
        buffer.setIndex(0, 0);
        buffer.writeCharSequence(content1, CharsetUtil.US_ASCII);
        buffer.markWriterIndex();
        buffer.skipBytes(content1.length());
        buffer.writeCharSequence(content2, CharsetUtil.US_ASCII);
        buffer.skipBytes(content2.length());
        assertTrue(buffer.readerIndex() <= buffer.writerIndex());

        try {
            buffer.resetWriterIndex();
        } finally {
            buffer.release();
        }
    }

public JobStatus getCurrentInitializerJobStatus()
    {
        // Get XWiki initializer job
        JobStatus jobStatus = getJobStatus();

        if (jobStatus == null) {
            return null;
        }

        // The XWiki initialization is not done yet
        if (jobStatus.getState() != State.FINISHED) {
            return jobStatus;
        }

        // If XWiki initialization did not failed
        if (this.xwiki != null) {
            // Get current wiki initializer job
            Job wikiJob = this.xwiki.getWikiInitializerJob(this.context.getWikiId());

            jobStatus = wikiJob != null ? wikiJob.getStatus() : null;
        }

        return jobStatus;
    }

